코드:
static class Greeter {
    private final String prefix;
    Greeter(String prefix) { this.prefix = prefix; }
    String greet(String name) { return prefix + ", " + name; }
}

@Configuration
static class AppConfig {
    @Bean
    Greeter greeter() { return new Greeter("Hello"); }
}

var ctx = new AnnotationConfigApplicationContext(AppConfig.class);
Greeter g = ctx.getBean(Greeter.class);
System.out.println(g.greet("Spring"));

static class Greeter { }

@Configuration
static class AppConfig {
    @Bean
    Greeter greeter() { return new Greeter(); }
}

var ctx = new AnnotationConfigApplicationContext(AppConfig.class);
Greeter a = ctx.getBean(Greeter.class);
Greeter b = ctx.getBean(Greeter.class);
System.out.println(a == b);

