interface Payment { }
static class Card implements Payment { }
static class Cash implements Payment { }

@Configuration
static class AppConfig {
    @Bean Payment card() { return new Card(); }
    @Bean Payment cash() { return new Cash(); }
}

var ctx = new AnnotationConfigApplicationContext(AppConfig.class);
try {
    ctx.getBean(Payment.class);
} catch (NoUniqueBeanDefinitionException e) {
    System.out.println(e.getNumberOfBeansFound());
}

