interface OrderRepository { String name(); }

@Repository
static class MemoryOrderRepository implements OrderRepository {
    public String name() { return "memory"; }
}

@Service
static class OrderService {
    private final OrderRepository repository;
    OrderService(OrderRepository repository) { this.repository = repository; }
    String storage() { return repository.name(); }
}

@Configuration @ComponentScan
static class AppConfig { }

var ctx = new AnnotationConfigApplicationContext(AppConfig.class);
System.out.println(ctx.getBean(OrderService.class).storage());

