static class Helper { }

@Component
static class Client {
    private final Optional<Helper> helper;
    Client(Optional<Helper> helper) { this.helper = helper; }
    boolean hasHelper() { return helper.isPresent(); }
}

@Configuration @ComponentScan
static class AppConfig { }

var ctx = new AnnotationConfigApplicationContext(AppConfig.class);
System.out.println(ctx.getBean(Client.class).hasHelper());

