interface Plugin { String name(); }

@Component @Order(2)
static class PluginA implements Plugin { public String name() { return "A"; } }

@Component @Order(1)
static class PluginB implements Plugin { public String name() { return "B"; } }

@Component
static class Host {
    final List<Plugin> plugins;
    Host(List<Plugin> plugins) { this.plugins = plugins; }
}

@Configuration @ComponentScan
static class AppConfig { }

var ctx = new AnnotationConfigApplicationContext(AppConfig.class);
StringBuilder sb = new StringBuilder();
for (Plugin p : ctx.getBean(Host.class).plugins) sb.append(p.name());
System.out.println(sb);

