@Component @Scope("prototype")
static class Proto {
    static int count = 0;
    Proto() { count++; }
}

@Component
static class Client {
    final Proto proto;
    Client(Proto proto) { this.proto = proto; }
}

@Configuration @ComponentScan
static class AppConfig { }

var ctx = new AnnotationConfigApplicationContext(AppConfig.class);
ctx.getBean(Client.class);
ctx.getBean(Client.class);
System.out.print(Proto.count + " ");
ctx.getBean(Proto.class);
ctx.getBean(Proto.class);
System.out.println(Proto.count);

