@Service
static class PriceService {
    private int price;   // 상태를 가진 싱글톤 (잘못된 설계)
    void order(int price) { this.price = price; }
    int getPrice() { return price; }
}

@Configuration @ComponentScan
static class AppConfig { }

var ctx = new AnnotationConfigApplicationContext(AppConfig.class);
PriceService userA = ctx.getBean(PriceService.class);
PriceService userB = ctx.getBean(PriceService.class);
userA.order(10000);
userB.order(20000);
System.out.println(userA.getPrice());

static class Client {
    void start() { System.out.print("start "); }
    void stop()  { System.out.print("stop"); }
}

@Configuration
static class AppConfig {
    @Bean(initMethod = "start", destroyMethod = "stop")
    Client client() { return new Client(); }
}

var ctx = new AnnotationConfigApplicationContext(AppConfig.class);
ctx.close();

