@Component
static class AppInfo {
    @Value("${app.name:demo}")
    String name;
}

@Configuration @ComponentScan
static class AppConfig { }

var ctx = new AnnotationConfigApplicationContext();
ctx.getEnvironment().getPropertySources()
   .addFirst(new MapPropertySource("custom", Map.of("app.name", "shop")));
ctx.register(AppConfig.class);
ctx.refresh();
System.out.println(ctx.getBean(AppInfo.class).name);

interface Storage { String name(); }

@Component @Profile("dev")
static class LocalStorage implements Storage { public String name() { return "local"; } }

@Component @Profile("prod")
static class S3Storage implements Storage { public String name() { return "s3"; } }

@Configuration @ComponentScan
static class AppConfig { }

var ctx = new AnnotationConfigApplicationContext();
ctx.getEnvironment().setActiveProfiles("dev");
ctx.register(AppConfig.class);
ctx.refresh();
System.out.println(ctx.getBean(Storage.class).name());

